{% set current_case_view = "package" %}{% set current_package = package %}
{% include "case/_compact_header.html" %}
{% if done %}{{ done_banner(done.key, done.text, undo=done.undo, csrf_token=csrf_token) }}{% endif %}
<div class="package-workspace" data-state="package-workspace">
<div class="package-main">
<header class="b-package-heading"><div><p class="b-kicker">Package</p><h1 id="package-contents-title" tabindex="-1">Package contents</h1></div><p class="b-package-badge">{{ tag(chip.kind, chip.label) }} · v{{ package.version }}</p></header>

{% if feature_enabled("offline_market_mode") or feature_enabled("declared_limits") or feature_enabled("presentation_mode") %}<details class="dossier-fold" data-state="connection-fold"><summary>Connection and offline capture</summary>{% include "features/offline_market_mode/_entry.html" %}</details>{% endif %}
{% if context_limitations %}
{% call banner("info", "paypal-limitations", "What PayPal did not return") %}
  <ul>{% for l in context_limitations %}<li>{{ l }}</li>{% endfor %}</ul>
  <p>These checks stay "Present, but Proofie cannot verify" until you add the missing detail yourself. {% if not sent_version %}<a href="#shipment-details">Type the details</a>{% endif %}</p>
  {% if tracking_current %}<p class="field-hint">The package has tracking {{ mono_id(tracking_current) }}{% if carrier_current %} ({{ carrier_display_name(carrier_current) }}){% endif %}; that does not mean it is registered in PayPal.</p>{% endif %}
{% endcall %}
{% endif %}

{% if sent_view.kind == 'partial' %}<p data-state="sent-read-only">Sent - read-only. Proofie sent this version{% if sent_view.when %} at {{ sent_view.when|when }}{% endif %}, and when Proofie checked, PayPal showed the statements without {{ record.missing_files|join(", ") if record.missing_files else "every file" }}. This version cannot change.</p>
{% else %}<p data-state="sent-read-only">Sent - read-only. PayPal's record showed this version at {{ sent_view.when|when }}, when Proofie checked. This version cannot change.</p>{% endif %}
{% if later.removed %}<p data-state="removed-after-send">{{ later.removed }}</p>{% endif %}

{# A sent version has no edit sections: the links that point at them land on these lines. #}
<li id="shipment-details"><span id="shipment-fold"></span><span id="field-tracking_number"></span>Tracking number: {{ mono_id(sent_view.tracking) }}{% if sent_view.carrier %} ({{ sent_view.carrier }}){% endif %}</li>
<li id="attachments"><span id="files-fold"></span>Files: {% if sent_view.files %}{% for f in sent_view.files %}{{ mono_id(f) }}{% if not loop.last %}, {% endif %}{% endfor %}{% else %}none{% endif %}</li>

