{% set states = check_rows|map(attribute='tag_state')|list %}
{% if record.state == 'none' %}<p data-state="{{ send_state.state }}">{{ tag('info' if send_state.state == 'approved' else 'todo', send_status) }}</p>{% endif %}
{% if send_state.state == "confirmed" %}<p data-state="package-sent">{{ tag('ok', 'Sent to PayPal') }}</p>
{% if 'bad' in states or 'warn' in states %}<p class="hint" data-state="checks-after-sending">Checks run after sending: {{ 'a difference needs review' if 'bad' in states else 'some facts cannot be verified' }}. Nothing was re-sent.</p>{% endif %}
{% else %}<p>{{ tag('bad' if 'bad' in states else 'warn' if 'warn' in states else 'ok', 'Needs attention' if 'bad' in states else 'Some facts cannot be verified' if 'warn' in states else 'Checks complete') }}</p>{% endif %}

