{% set optional_open = namespace(value=false) %}
{% for item in shipment_fields if item[0] not in ['tracking_number','carrier'] and item[0] not in shipment_needed %}
{% set name = item[0] %}{% if form_errors.get(name) or form_values.get(name, manual_fields.get(name, {}).get('value', '')) %}{% set optional_open.value = true %}{% endif %}
{% endfor %}
<details data-state="optional-details"{% if optional_open.value %} open{% endif %}><summary>Optional details that help the checks</summary>

{% for source_doc in c.source_documents %}
<div class="claim-source-detail" data-source-document="{{ source_doc.id }}">
  <p>Source file: {{ source_doc.filename }} · {% if source_doc.extraction_ok %}text extracted{% else %}text extraction unavailable{% endif %}{% if not hosted_demo() %} · <a href="/disputes/{{ dispute_id }}/documents/{{ source_doc.id }}/original">Open original</a>{% endif %}</p>
  {% if source_doc.extraction_ok and source_doc.extracted_text %}<blockquote><strong>Extracted text excerpt — not the original:</strong> {{ source_doc.extracted_text[:320] }}{% if source_doc.extracted_text|length > 320 %}…{% endif %}</blockquote>{% elif not source_doc.extraction_ok %}<p>The original is available; its text could not be extracted. Review the original directly. This does not confirm the statement.</p>{% endif %}
</div>
{% endfor %}

{% set verified_rows = check_rows|selectattr("tag_state", "equalto", "ok")|list %}
{% set open_rows = check_rows|rejectattr("tag_state", "equalto", "ok")|list %}
{% for group_name, group_rows in (("open", open_rows), ("verified", verified_rows)) if group_rows %}
{% if group_name == "verified" %}<details data-state="verified-checks"><summary>{{ verified_rows|length }} {{ "check" if verified_rows|length == 1 else "checks" }} verified</summary>{% endif %}
